-- Schema v1 (T-013). Specification: docs/DATA_MODEL.md.
--
-- This file has two kinds of statements:
--   1. statements generated by `prisma migrate dev --create-only` from prisma/schema.prisma
--      (marked CreateEnum, CreateTable, CreateIndex, AddForeignKey), unchanged;
--   2. hand-written statements that the Prisma schema cannot express (marked RAW SQL):
--      the sequence for order numbers (below, because the "Order" table default needs it),
--      and, at the end of the file, every CHECK constraint, the partial unique indexes, and
--      the single "MarketplaceSettings" row.
-- The hand-written parts are listed in docs/DATA_MODEL.md section 13. Prisma does not manage
-- them: a later migration that changes one of them must be written by hand as well.

-- RAW SQL: sequence behind the default of "Order"."orderNumber" (DATA_MODEL.md section 10).
-- The upper limit of 16 digits keeps an order number within 24 characters ("OD" + 6 + 16).
CREATE SEQUENCE "order_number_seq" AS bigint INCREMENT BY 1 MINVALUE 1 MAXVALUE 9999999999999999 START WITH 1 NO CYCLE;

