-- =============================================================================================
-- RAW SQL from here to the end of the file (DATA_MODEL.md section 13).
-- Constraint and index names are part of the contract: services recognise a violation by name.
-- =============================================================================================

-- RAW SQL: partial unique indexes

-- One default address per user.
CREATE UNIQUE INDEX "Address_userId_default_key" ON "Address"("userId") WHERE "isDefault";

-- One open application per user.
CREATE UNIQUE INDEX "SellerApplication_userId_pending_key" ON "SellerApplication"("userId") WHERE "status" = 'PENDING';

-- SKU unique per store among products that are not archived.
CREATE UNIQUE INDEX "Product_storeId_sku_live_key" ON "Product"("storeId", "sku") WHERE "status" <> 'ARCHIVED';

-- RAW SQL: check constraints

ALTER TABLE "Address"
  ADD CONSTRAINT "Address_postalCode_check" CHECK ("postalCode" ~ '^[0-9]{5}$');

-- The stock bound is the bound of the column. The seller's entry limit of 1,000,000 is
-- deliberately not a check: a stock restore must never be refused (DATA_MODEL.md section 11).
ALTER TABLE "Product"
  ADD CONSTRAINT "Product_priceSatang_check" CHECK ("priceSatang" BETWEEN 100 AND 100000000),
  ADD CONSTRAINT "Product_stock_check" CHECK ("stock" BETWEEN 0 AND 1000000000),
  ADD CONSTRAINT "Product_contentRevision_check" CHECK ("contentRevision" >= 1);

ALTER TABLE "Upload"
  ADD CONSTRAINT "Upload_contentType_check" CHECK ("contentType" IN ('image/jpeg', 'image/png', 'image/webp')),
  ADD CONSTRAINT "Upload_sizeBytes_check" CHECK ("sizeBytes" BETWEEN 1 AND 5242880);

ALTER TABLE "ProductImage"
  ADD CONSTRAINT "ProductImage_sortOrder_check" CHECK ("sortOrder" BETWEEN 0 AND 7);

ALTER TABLE "CartItem"
  ADD CONSTRAINT "CartItem_quantity_check" CHECK ("quantity" BETWEEN 1 AND 99);

ALTER TABLE "Order"
  ADD CONSTRAINT "Order_itemsSubtotalSatang_check" CHECK ("itemsSubtotalSatang" >= 0),
  ADD CONSTRAINT "Order_shippingTotalSatang_check" CHECK ("shippingTotalSatang" >= 0),
  ADD CONSTRAINT "Order_grandTotalSatang_check" CHECK ("grandTotalSatang" BETWEEN 0 AND 2000000000),
  ADD CONSTRAINT "Order_grandTotalSatang_sum_check" CHECK ("grandTotalSatang" = "itemsSubtotalSatang"::bigint + "shippingTotalSatang"),
  ADD CONSTRAINT "Order_shipPostalCode_check" CHECK ("shipPostalCode" ~ '^[0-9]{5}$'),
  ADD CONSTRAINT "Order_paidAt_check" CHECK (("paymentStatus" = 'PAID') = ("paidAt" IS NOT NULL));

ALTER TABLE "SellerOrder"
  ADD CONSTRAINT "SellerOrder_itemsSubtotalSatang_check" CHECK ("itemsSubtotalSatang" >= 0),
  ADD CONSTRAINT "SellerOrder_shippingFeeSatang_check" CHECK ("shippingFeeSatang" BETWEEN 0 AND 100000),
  ADD CONSTRAINT "SellerOrder_commissionRateBps_check" CHECK ("commissionRateBps" BETWEEN 0 AND 10000);

ALTER TABLE "OrderItem"
  ADD CONSTRAINT "OrderItem_quantity_check" CHECK ("quantity" BETWEEN 1 AND 99),
  ADD CONSTRAINT "OrderItem_unitPriceSatang_check" CHECK ("unitPriceSatang" BETWEEN 100 AND 100000000),
  ADD CONSTRAINT "OrderItem_lineTotalSatang_check" CHECK ("lineTotalSatang" = "unitPriceSatang"::bigint * "quantity"),
  ADD CONSTRAINT "OrderItem_cartReturn_pair_check" CHECK (("cartQuantityBeforeReturn" IS NULL) = ("cartQuantityAfterReturn" IS NULL)),
  ADD CONSTRAINT "OrderItem_cartQuantityBeforeReturn_check" CHECK ("cartQuantityBeforeReturn" BETWEEN 0 AND 99),
  ADD CONSTRAINT "OrderItem_cartQuantityAfterReturn_check" CHECK ("cartQuantityAfterReturn" BETWEEN 1 AND 99),
  ADD CONSTRAINT "OrderItem_cartQuantityAfterReturn_max_check" CHECK ("cartQuantityAfterReturn" <= "cartQuantityBeforeReturn" + "quantity");

ALTER TABLE "Payment"
  ADD CONSTRAINT "Payment_amountSatang_check" CHECK ("amountSatang" BETWEEN 0 AND 2000000000);

ALTER TABLE "Shipment"
  ADD CONSTRAINT "Shipment_deliveredAt_check" CHECK ("deliveredAt" IS NULL OR "deliveredAt" >= "shippedAt");

ALTER TABLE "Review"
  ADD CONSTRAINT "Review_rating_check" CHECK ("rating" BETWEEN 1 AND 5);

ALTER TABLE "MarketplaceSettings"
  ADD CONSTRAINT "MarketplaceSettings_id_check" CHECK ("id" = 1),
  ADD CONSTRAINT "MarketplaceSettings_flatShippingFeeSatang_check" CHECK ("flatShippingFeeSatang" BETWEEN 0 AND 100000),
  ADD CONSTRAINT "MarketplaceSettings_commissionRateBps_check" CHECK ("commissionRateBps" BETWEEN 0 AND 10000),
  ADD CONSTRAINT "MarketplaceSettings_commissionRateBps_whole_percent_check" CHECK ("commissionRateBps" % 100 = 0);

-- RAW SQL: the single settings row with the confirmed initial values (D-017): a flat shipping
-- fee of 4,000 satang (40 THB) and a commission of 500 basis points (5 percent). It is inserted
-- here, not by the seed, because the seed never runs in production.
INSERT INTO "MarketplaceSettings" ("id", "flatShippingFeeSatang", "commissionRateBps", "updatedById", "updatedAt")
VALUES (1, 4000, 500, NULL, CURRENT_TIMESTAMP);
